from z3 import *

# We need to find a graph with 21 vertices, girth >= 6, and degree between 3 and 5.
# Let's use a SAT/SMT approach.

n = 21

# Create boolean variables for edges
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i, j)] = Bool(f'e_{i}_{j}')

solver = Optimize()

# Constraint: each vertex has degree between 3 and 5
for v in range(n):
    degree = Sum([If(edges[(min(v, u), max(v, u))], 1, 0) for u in range(n) if u != v])
    solver.add(degree >= 3)
    solver.add(degree <= 5)

# Constraint: no cycles of length 3, 4, or 5 (girth >= 6)

# No triangles (cycles of length 3)
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            solver.add(Not(And(edges[(i, j)], edges[(j, k)], edges[(i, k)])))

# No 4-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                # Check all possible 4-cycles among these 4 vertices
                # A 4-cycle uses exactly 4 edges forming a cycle
                # Possible 4-cycles: (i,j,k,l), (i,j,l,k), (i,k,j,l)
                solver.add(Not(And(edges[(i, j)], edges[(j, k)], edges[(k, l)], edges[(i, l)])))
                solver.add(Not(And(edges[(i, j)], edges[(j, l)], edges[(l, k)], edges[(i, k)])))
                solver.add(Not(And(edges[(i, k)], edges[(k, j)], edges[(j, l)], edges[(i, l)])))

print("Constraints added, solving...")
result = solver.check()
print(f"Result: {result}")

if result == sat:
    m = solver.model()
    edge_list = []
    for (i, j), var in edges.items():
        if m.evaluate(var) == True:
            edge_list.append((i, j))
    print(f"Number of edges: {len(edge_list)}")
    print(f"Edges: {edge_list}")

    # Verify degrees
    degrees = [0] * n
    for u, v in edge_list:
        degrees[u] += 1
        degrees[v] += 1
    print(f"Degrees: {degrees}")
    print(f"Min degree: {min(degrees)}, Max degree: {max(degrees)}")
else:
    print("UNSATISFIABLE")

from z3 import *

n = 21

# Create boolean variables for edges
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i, j)] = Bool(f'e_{i}_{j}')

def get_edge(u, v):
    if u > v:
        u, v = v, u
    return edges[(u, v)]

solver = Solver()

# Constraint: each vertex has degree between 3 and 5
for v in range(n):
    degree = Sum([If(get_edge(v, u), 1, 0) for u in range(n) if u != v])
    solver.add(degree >= 3)
    solver.add(degree <= 5)

# No triangles (cycles of length 3)
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            solver.add(Not(And(get_edge(i, j), get_edge(j, k), get_edge(i, k))))

# No 4-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                # All possible 4-cycles among 4 vertices
                solver.add(Not(And(get_edge(i, j), get_edge(j, k), get_edge(k, l), get_edge(i, l))))
                solver.add(Not(And(get_edge(i, j), get_edge(j, l), get_edge(l, k), get_edge(i, k))))
                solver.add(Not(And(get_edge(i, k), get_edge(k, j), get_edge(j, l), get_edge(i, l))))

print("Constraints added, solving...")
result = solver.check()
print(f"Result: {result}")

if result == sat:
    m = solver.model()
    edge_list = []
    for (i, j), var in edges.items():
        if m.evaluate(var) == True:
            edge_list.append((i, j))
    print(f"Number of edges: {len(edge_list)}")
    print(f"Edges: {edge_list}")

    # Verify degrees
    degrees = [0] * n
    for u, v in edge_list:
        degrees[u] += 1
        degrees[v] += 1
    print(f"Degrees: {degrees}")
    print(f"Min degree: {min(degrees)}, Max degree: {max(degrees)}")
else:
    print("UNSATISFIABLE")

