n = 21

# Build adjacency list
adj = {i: set() for i in range(n)}
for u, v in edge_list:
    adj[u].add(v)
    adj[v].add(u)

# Check degrees
degrees = [len(adj[i]) for i in range(n)]
print(f"Degrees: {degrees}")
print(f"Min degree: {min(degrees)}, Max degree: {max(degrees)}")
assert all(3 <= d <= 5 for d in degrees), "Degree constraint violated!"

# Check for triangles (3-cycles)
triangles = 0
for i in range(n):
    for j in adj[i]:
        if j > i:
            for k in adj[j]:
                if k > j and k in adj[i]:
                    triangles += 1
                    print(f"Triangle found: ({i}, {j}, {k})")
print(f"Triangles: {triangles}")
assert triangles == 0, "Found triangles!"

# Check for 4-cycles
four_cycles = 0
for i in range(n):
    for j in adj[i]:
        if j > i:
            for k in adj[j]:
                if k > j:
                    for l in adj[k]:
                        if l > k and l in adj[i]:
                            four_cycles += 1
                            print(f"4-cycle found: ({i}, {j}, {k}, {l})")
print(f"4-cycles: {four_cycles}")
assert four_cycles == 0, "Found 4-cycles!"

# Check for 5-cycles
five_cycles = 0
for i in range(n):
    for j in adj[i]:
        if j > i:
            for k in adj[j]:
                if k > j:
                    for l in adj[k]:
                        if l > k:
                            for m in adj[l]:
                                if m > l and m in adj[i]:
                                    five_cycles += 1
                                    print(f"5-cycle found: ({i}, {j}, {k}, {l}, {m})")
print(f"5-cycles: {five_cycles}")
assert five_cycles == 0, "Found 5-cycles!"

print("\nAll constraints verified! Solution is valid.")
